# These are direct, stable elementary explanations; not added from failed eval answers.
TEXT = [
('sensor','What does a sensor do?','It detects or measures a physical property, such as light or pressure.'),
('duration','What does duration mean?','Duration is the amount of time something lasts.'),
('distance','What does distance describe?','Distance describes how far apart two points are.'),
('volume','What does the volume of a container describe?','It describes how much space the container can hold.'),
('speed','How is speed different from distance?','Speed is distance traveled per unit of time; distance describes how far something travels.'),
('humidity','What does humidity describe?','Humidity describes the amount of water vapor in the air.'),
('pressure','What is pressure?','Pressure is force acting per unit area.'),
('battery','What does a battery supply to a circuit?','A battery supplies electrical energy to the circuit.'),
('lever','What is a lever?','A lever is a rigid bar that pivots around a point called a fulcrum.'),
('pulley','What does a pulley do?','A pulley guides a rope or cable and can change the direction of a pulling force.'),
('reflection','What is reflection of light?','Reflection is light bouncing from a surface.'),
('transparent','What does transparent mean?','A transparent material lets light pass through so you can see objects behind it.'),
('opaque','What does opaque mean?','An opaque material prevents light from passing through it.'),
('dissolve','What happens when sugar dissolves in water?','The sugar particles disperse throughout the water to form a solution.'),
('solute','What is the solute in a saltwater solution?','Salt is the solute; water is the solvent.'),
('mixture','What is a mixture?','A mixture contains substances combined physically rather than chemically bonded together.'),
('sieve','What does a sieve separate?','A sieve separates particles by size.'),
('prediction','What is a scientific prediction?','It states an expected outcome that can be tested.'),
('observation','How is an observation different from an inference?','An observation records what is noticed or measured; an inference interprets that evidence.'),
('control','Why keep some variables constant in an experiment?','It helps isolate the effect of the variable being changed.'),
]


def authored_rows():
    # Preserve old semantic family IDs: earlier reserved families cannot be
    # smuggled into training under a new run number.
    rows=[r for r in previous_rows() if r['bucket'] not in ('social','grounded','missing')]
    def add(bucket,family,messages,**extra):
        rows.append(dict(bucket=bucket,component='python' if bucket=='python' else 'constraints' if bucket=='format' else 'chat',group='reviewed-020:'+family,messages=messages,provenance=PROVENANCE,**extra))
    # Query target varies independently of record order and numeric magnitude.
    names=['Alma','Cleo','Dion','Esme','Finn','Gita','Hugo','Inez','Jori','Lars','Mona','Nico']
    schemas=['pod','aisle','bay','dock','tray','vault','cart','suite','zone','cell','slot','row','floor','unit','stall','table','berth','block','shed','cubby']
    for si,schema in enumerate(schemas):
        for v in range(12):
            people=[names[(si+v+i*3)%len(names)] for i in range(3)]
            values=[str((v*13+si*7+i*19)%89+10) for i in range(3)]
            records=list(zip(people,values))[:2 if v%2==0 else 3];shift=v%len(records);records=records[shift:]+records[:shift]
            fact='; '.join(f'{name} uses {schema} {value}' for name,value in records)+'.'
            for position,(who,answer) in enumerate(records):
                prompt=[f'Record: {fact} Return just the {schema} number assigned to {who}.',f'Using this record: {fact} Which {schema} belongs to {who}? Give the number alone.',f'{fact} Reply only with the {schema} number for {who}.'][v%3]
                add('grounded','record-'+schema,pair(prompt,answer),selection_stratum=str(position),requested_entity=who,requested_position=position,records=records,rules=[dict(kind='exact',args=[answer])])
                updated=str(120+v+position)
                add('followup','record-'+schema,pair('Remember: '+fact,'I have noted the assignments.')+pair(f'Change only {who} to {schema} {updated}.',f'{who} now uses {schema} {updated}.')+pair(f'Give only the latest {schema} number for {who}.',updated),selection_stratum=str(position),rules=[dict(kind='exact',args=[updated])])
            add('missing','record-'+schema,pair(f'Record: {fact} Give {people[0]}’s departure time, or "Not provided" if the record does not state it.','Not provided'),rules=[dict(kind='exact',args=['Not provided'])])
            # Request a field name, as distinct from the field's content.
            add('format','record-'+schema,pair(f'Record: {fact} The field holding the assigned location is called {schema}. Return only that field name.',schema),rules=[dict(kind='exact',args=[schema])])
    objects=['draft','story','memo','invitation','poem','outline','agenda','article','note','message','plan','recipe','description','announcement','caption','report','letter','schedule','paragraph','summary']
    starts=['Hey there, can I ask something?','Good morning, can you help?','Hello, I have a small task.','Hi there, let us talk.']
    greeting=['Hi! What would you like to ask?','Hello! How can I help?','Hello! Tell me about the task.','Hi! What is on your mind?']
    gratitude=['Thanks, I understand it now.','I appreciate the explanation.','That helped, thank you.','Thanks for clearing that up.']
    goodbye=['I need to leave the chat now.','That is all I needed. Bye!','Let us pause here. Goodbye.','I am signing off for now.']
    casual=['Anything new with you?','How is your day going?','What are you doing here?','Are you busy right now?']
    capability=['What kinds of tasks do you handle?','What could I ask you to do?','How can you assist me?','Can you describe your useful skills?']
    for i,obj in enumerate(objects):
        for v in range(4):
            missing=pair(f'I would like help with a {obj}, but I have not shared it.',f'Please share the {obj} and what you want to change.')
            prefix=pair(starts[v],greeting[v])
            add('social','social-'+obj,prefix+missing,selection_stratum='greeting:context',social_intent='greeting')
            add('social','social-'+obj,missing+pair(gratitude[v],"You're welcome!"),selection_stratum='thanks:context',social_intent='thanks')
            add('social','social-'+obj,missing+pair(goodbye[v],'Goodbye! Take care.'),selection_stratum='farewell:context',social_intent='farewell')
            add('social','social-'+obj,missing+pair(casual[v],'I am here and ready to chat. What would you like to talk about?'),selection_stratum='casual:context',social_intent='casual')
            add('social','social-'+obj,missing+pair(capability[v],'I can answer questions, explain ideas, help with writing, and work on simple Python code.'),selection_stratum='capability:context',social_intent='capability')
    # Standalone intents complement task-containing histories. These are known
    # foundational intents, not an independent held-out discovery panel.
    direct={
      'greeting':(['Hello there!','Hey, hello!','Hi, good to meet you.','Good evening, assistant.','Hello, are you available?','Hi, can you respond?','Hello from me.','A quick hello!','Hi, I am ready to chat.','Hey, good to see you.','Hello, let us begin.','Hi, can we get started?','Greetings, assistant!','Hi, I have something to ask.','Hello, may we talk?','Hey, I could use a hand.','Hi, nice to meet you.','Hello, I am here.','Good morning to you.','Good afternoon to you.','Hi, are you ready?','Hello, I have a question.','Hey there, assistant.','Hello, thanks for being here.'],'Hello! How can I help you?'),
      'thanks':(['Thank you for explaining it.','Thanks, I got it.','That is useful, thank you.','I appreciate the clear answer.','Thanks for that response.','You answered my question, thanks.','Thank you for the assistance.','Many thanks for your explanation.','I understand now. Thank you.','That cleared it up for me.','Thanks for your patience.','Thank you, I found that useful.','I am grateful for the explanation.','Thanks, that worked.','That makes sense now, thank you.','Thanks for explaining the example.','I appreciate your time.','Thank you for walking through it.','Thanks for the clarification.','That was exactly what I needed, thanks.','Your explanation helped, thanks.','I appreciate the help with that.','Great, thank you for answering.','Thanks for making it clear.'],"You're welcome!"),
      'farewell':(['Bye, talk another time.','Goodbye, I am leaving now.','See you another time.','I will close the chat now. Bye.','That is everything. Goodbye.','Time to leave. Bye!','I have to go, take care.','I am done for now. Goodbye.','See you next time, assistant.','Bye, and thanks for the help.','Let us finish here. Goodbye.','I am leaving the conversation. Bye.','Talk again later.','Goodbye and take care.','Bye, I will be back later.','I am heading off. Goodbye.','That concludes our chat. Bye.','Have a good evening. Goodbye.','I need to sign off. Bye.','Goodbye, until another time.','Bye, we can continue later.','I will go now. See you.','Take care, I am leaving now.','See you later, goodbye.'],'Goodbye! Take care.'),
      'casual':(['How are you doing in this chat?','What are you doing at the moment?','Are you around for a chat?','How are things with you?','What is new with you?','Are you ready to talk?','What are you up to now?','Are you there for a conversation?','How is it going with you?','What is happening with you?','Are you free to chat?','What have you got going on?','Are you available to talk?','How are you feeling about chatting?','What is going on with you?','Want to chat for a bit?','Are you working on anything?','How is your afternoon going?','How is your evening going?','Are you here with me?','What are you busy with?','Are you still ready to chat?','What is up at your end today?','Would you like to talk?'],'I am here and ready to chat. What would you like to talk about?'),
      'capability':(['What help is available from you?','What can we do in this conversation?','What tasks are you able to assist with?','Which kinds of questions can I ask?','What are some useful things you can do?','Could you give examples of your skills?','How can I use your help?','What sort of assistance do you provide?','What topics can we work on?','Tell me what you can assist with.','What can you do for a user?','Describe your help in one sentence.','Which tasks can I bring to you?','What do you offer in this chat?','What is your role here?','What are your main abilities?','How might you help with a small task?','Can you explain the help you offer?','What types of work could we do?','What kinds of assistance can you give?','What can I use this chat for?','What useful support can you provide?','What could you help me learn or write?','Which tasks are within your scope?'],'I can answer questions, explain ideas, help with writing, and work on simple Python code.')}
    for intent,(prompts,answer) in direct.items():
        for prompt in prompts:
            add('social','socialdirect-'+intent,pair(prompt,answer),selection_stratum=intent+':direct',social_intent=intent)
    # Request paraphrases keep the original semantic family ID when available.
    # Earlier held-out objects stay held out despite changing their wording.
    for obj in ['paragraph','Python script','recipe','email draft','list','short story','instructions','table','plan','question','sentence','code snippet','summary','message','outline','schedule','shopping list','function','text','description']:
        for prompt in [f'I need another pair of eyes on my {obj}, which I have not pasted yet.',
                       f'Would you help with a {obj} once I provide it?',
                       f'What information do you need before reviewing my {obj}?',
                       f'My next message will contain a {obj} for you to look at.',
                       f'I am asking for help with my {obj}; its contents are not here.',
                       f'Could you tell me what to send so you can check my {obj}?',
                       f'I have a {obj} to discuss. What should I provide first?',
                       f'Before I paste my {obj}, what do you need from me?']:
            add('clarify','missing-'+obj,pair(prompt,f'Please share the {obj} and what you would like help with.'),review_contract='Requests the actual missing input; does not fabricate contents.')
            rows[-1]['group']='reviewed-019:missing-'+obj
    for family,q,answer in TEXT:
        add('concise','knowledge-'+family,pair(q,answer),review_contract='Reviewed elementary definition; direct answer with no extra invented context.')
        add('concise','knowledge-'+family,pair(q+' Keep it brief.',answer),review_contract='Same definition with explicit brevity.')
        add('followup','knowledge-'+family,pair(q,answer)+pair('Can you restate that briefly?',answer),review_contract='Short response remains grounded in the preceding definition.')
    for family,args,body,meaning,inputs,expected,explanation in PYTHON:
        for v in range(8):
            fn=f'{family}_{v+1}';code=f'def {fn}({args}):\n'+''.join('    '+line+'\n' for line in body.splitlines())
            tests=[dict(function=fn,args_literal=repr(a),expected_literal=repr(e)) for a,e in zip(inputs,expected)]
            for mode in ('named','unnamed','followup','docstring'):
                requested=None if mode=='unnamed' else fn;doc=mode=='docstring';target=code
                instruction=f'Write a Python function to {meaning}.' if requested is None else f'Write {fn}({args}) in Python to {meaning}.'
                if doc:
                    instruction+=' Include a docstring.';target=code.split('\n',1)[0]+'\n    """'+meaning[0].upper()+meaning[1:]+'."""\n'+code.split('\n',1)[1]
                instruction+=' Return only a Python code block.';answer='```python\n'+target.rstrip()+'\n```'
                contract=dict(function=requested,code_only=True,docstring=doc)
                assert all(python_checks(answer,tests,**contract).values()),family
                messages=pair(instruction,answer)
                if mode=='followup':
                    messages+=pair(f'What does {fn}('+', '.join(repr(x) for x in inputs[1])+') return? Give only the Python value.',repr(expected[1]))+pair('Briefly explain why it returns that value.',explanation)
                add('python','python-'+family,messages,functional_assertions=tests,python_contract=contract,review_contract='Explicit domain, four literal oracles, edge cases and code-grounded follow-up.')
    return list({digest(json.dumps(r['messages'],sort_keys=True)):r for r in rows}.values())
